import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { $RefParser } from '@apidevtools/json-schema-ref-parser';
import { compile } from 'json-schema-to-typescript';
import { format, resolveConfig } from 'prettier';

const target = fileURLToPath(new URL('../src/contract/nodes.generated.ts', import.meta.url));
const kinds = ['sync', 'publish', 'accept', 'delivery'] as const;
type ContractSchema = Parameters<typeof compile>[0];
const blocks: string[] = [
  '/* Generated by wetamp/scripts/generate-node-contracts.ts. Do not edit. */',
];
const closeTypeObjects = (value: unknown): void => {
  if (!value || typeof value !== 'object') return;
  if (!Array.isArray(value)) {
    const object = value as Record<string, unknown>;
    if (object.type === 'object' && object.properties) object.additionalProperties = false;
  }
  for (const child of Object.values(value)) closeTypeObjects(child);
};
for (const kind of kinds) {
  const source = new URL(`../schemas/nodes/${kind}.schema.json`, import.meta.url);
  const schema = JSON.parse(readFileSync(source, 'utf8')) as ContractSchema;
  const bundledSchema: ContractSchema =
    kind === 'accept'
      ? await $RefParser.bundle<ContractSchema>(fileURLToPath(source), schema, {})
      : schema;
  const typeSchema = structuredClone(bundledSchema);
  closeTypeObjects(typeSchema);
  blocks.push(
    await compile(typeSchema, String(schema.title), {
      bannerComment: '',
      ignoreMinAndMaxItems: true,
    })
  );
  if (kind === 'sync')
    blocks.push(
      "export type SyncResult = SyncOutput extends infer S ? S extends { generation: number } ? Omit<S, 'generation'> : never : never;"
    );
  if (kind === 'publish') blocks.push('export type PublishResult = PublishOutput;');
  if (kind === 'accept')
    blocks.push(
      "export type DeliveryDecision = AcceptOutput['decision'];",
      "export type Completion = NonNullable<DeliveryDecision['requirements']>;",
      "export type CheckFailure = NonNullable<AcceptOutput['failures']>[number];",
      "export type Disposition = Exclude<AcceptOutput['disposition'], 'suspend'>;",
      "export type Accept = Pick<AcceptOutput, 'ok' | 'diff_hash' | 'same'> & Partial<Omit<AcceptOutput, 'ok' | 'diff_hash' | 'same' | 'disposition'>> & { disposition?: Disposition };"
    );
  blocks.push(`export const ${kind}OutputFormat = ${JSON.stringify(bundledSchema)} as const;`);
}
const text = await format(blocks.join('\n'), {
  ...(await resolveConfig(target)),
  filepath: target,
});
if (process.argv.includes('--check')) {
  if (readFileSync(target, 'utf8') !== text)
    throw new Error('Node contracts drift: run bun run generate:node-contracts');
} else {
  writeFileSync(target, text);
}
